    "ref": "131",
    "subtitle": "Континент, що тримається на коренях космічного гігантського дерева",
    "concept": "Посеред безкрайньої зоряної порожнечі дрейфує колосальний материк, що сформувався на тисячах коренів: вони тягнуться через увесь материк і звисають у безодню космосу. Звичного горизонту немає: з країв континенту видно зорі, уламки інших земель і гігантські корені, що повільно рухаються в темряві.",
